    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  sentiment = JSON.parse(jsonStr.trim());
} catch (e) {
  // Fallback: keyword-based sentiment
  const text = input.user_text.toLowerCase();
  if (/angry|furious|terrible|worst|scam|fraud|steal|ridiculous/i.test(text)) {
    sentiment = { sentiment: 'angry', score: -0.8, is_urgent: true, confidence: 0.7 };
  } else if (/frustrated|annoyed|disappointed|upset|problem|issue|not working/i.test(text)) {
    sentiment = { sentiment: 'frustrated', score: -0.5, is_urgent: false, confidence: 0.7 };
  } else if (/urgent|asap|immediately|emergency|critical|help now/i.test(text)) {
    sentiment = { sentiment: 'urgent', score: -0.3, is_urgent: true, confidence: 0.8 };
  } else if (/thank|great|excellent|amazing|love|happy|pleased/i.test(text)) {
    sentiment = { sentiment: 'positive', score: 0.7, is_urgent: false, confidence: 0.7 };
  }
}

return [{
  ...input,
  sentiment: sentiment.sentiment,
  sentiment_score: sentiment.score,
  is_urgent: sentiment.is_urgent,
  sentiment_confidence: sentiment.confidence
}];

// Parse intent classification result
let input = {};
try {
  input = $('Parse Sentiment').item.json || {};
} catch (e) {
  input = $input.first().json || {};
}
const intentRaw = $input.first().json.text || $input.first().json.response || '{}';

let intent = { intent: 'general_chat', confidence: 0.5, sub_intent: null };

const allowedTechnicalSubIntents = new Set(['forgot_password_client_crm', 'forgot_password_trading_account', 'forgot_password_trading_app']);

function detectTechnicalSubIntent(textValue) {
  const text = String(textValue || '').toLowerCase();
  const hasCredentialSignal = /(login|log in|sign in|password|passcode|pass\b|pwd|credential|can't access|cannot access|forgot|forget|fogot|forgt|frgot|reset)/i.test(text);
  if (!hasCredentialSignal) return null;
  if (/\b(client\s*crm|crm|client\s*portal|client\s*area|cabinet|portal)\b/i.test(text)) return 'forgot_password_client_crm';
  if (/\b(mt4|mt5|trading\s*account|investor\s*password|master\s*password|account\s*login|account\s*number|trading\s+login)\b/i.test(text)) return 'forgot_password_trading_account';
  if (/\b(app|mobile|desktop|webtrader|platform|application)\b/i.test(text)) return 'forgot_password_trading_app';
  return 'forgot_password_trading_app';
}

try {
  let jsonStr = intentRaw;
  const jsonMatch = intentRaw.match(/```json?\s*([\s\S]*?)```/) || intentRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1] || jsonMatch[0];
  }
  intent = JSON.parse(jsonStr.trim());
  const normalizedSubIntent = String(intent.sub_intent || '').trim();
  if (String(intent.intent || '') === 'technical_support') {
    if (!allowedTechnicalSubIntents.has(normalizedSubIntent)) {
      intent.sub_intent = detectTechnicalSubIntent(input.user_text || input.message_text || '');
    }
  } else {
    intent.sub_intent = null;
  }
} catch (e) {
  // Fallback keyword-based intent
  const text = String(input.user_text || input.message_text || '').toLowerCase();
  const technicalSubIntent = detectTechnicalSubIntent(text);

  if (/human|agent|person|manager|supervisor|speak.*someone/i.test(text)) {
    intent = { intent: 'escalation_request', confidence: 0.95, sub_intent: null };
  } else if (technicalSubIntent) {
    intent = { intent: 'technical_support', confidence: 0.88, sub_intent: technicalSubIntent };
  } else if (/balance|equity|margin|account.*status|my account/i.test(text)) {
    intent = { intent: 'account_inquiry', confidence: 0.8, sub_intent: null };
  } else if (/deposit|withdraw|transfer|fund|payment/i.test(text)) {
    intent = { intent: 'deposit_withdrawal', confidence: 0.85, sub_intent: null };
  } else if (/position|trade|order|buy|sell|lot|pip/i.test(text)) {
    intent = { intent: 'trading_question', confidence: 0.8, sub_intent: null };
  } else if (/price|market|eurusd|gold|bitcoin|forecast/i.test(text)) {
    intent = { intent: 'market_analysis', confidence: 0.8, sub_intent: null };
  } else if (/document|kyc|verify|passport|id|proof/i.test(text)) {
    intent = { intent: 'document_verification', confidence: 0.85, sub_intent: null };
  } else if (/bonus|promotion|offer|referral/i.test(text)) {
    intent = { intent: 'promotions', confidence: 0.8, sub_intent: null };
  } else if (/complaint|unhappy|problem|issue|terrible|disappointed/i.test(text)) {
    intent = { intent: 'complaint', confidence: 0.75, sub_intent: null };
  }
}

return [{
  ...input,
  intent: intent.intent,
  intent_confidence: intent.confidence,
  sub_intent: intent.sub_intent || null
}];

