// Smart Router & Prompt Builder (restricted tools + natural out-of-scope replies)
let context = {};
try {
  const parseIntentItems = $('Parse Intent').all();
  if (parseIntentItems?.length) {
    const pairedItem = $input.first().pairedItem;
    if (pairedItem?.item?.length) {
      const sourceIndex = pairedItem.item[0].index || 0;
      context = parseIntentItems[sourceIndex]?.json || parseIntentItems[0].json || {};
    } else {
      context = parseIntentItems[0].json || {};
    }
  } else {
    context = $('Parse Intent').item.json || {};
  }
} catch (e) {
  context = $input.first().json || {};
}

const dbConfig = $input.first().json || {};
const userText = String(context.user_text || context.message_text || '').trim();
const intent = String(context.intent || 'general_chat');
const subIntent = String(context.sub_intent || '');
const intentConfidence = Number(context.intent_confidence || 0);

function detectCredentialScope(textValue) {
  const text = String(textValue || '').toLowerCase();
  const hasCredentialSignal = /(login|log in|sign in|password|passcode|pass\b|pwd|credential|can't access|cannot access|forgot|forget|fogot|forgt|frgot|reset)/i.test(text);
  if (!hasCredentialSignal) return null;
  if (/\b(client\s*crm|crm|client\s*portal|client\s*area|cabinet|portal)\b/i.test(text)) return 'credential_client_crm';
  if (/\b(mt4|mt5|trading\s*account|investor\s*password|master\s*password|account\s*login|account\s*number|trading\s+login)\b/i.test(text)) return 'credential_trading_account';
  if (/\b(app|mobile|desktop|webtrader|platform|application)\b/i.test(text)) return 'credential_trading_app';
  return 'credential_trading_app';
}

let scopeCategory = detectCredentialScope(userText) || "out_of_scope";
if (scopeCategory === 'out_of_scope') {
  if (/\b(balance|equity|margin|account|wallet|account type|account status)\b/i.test(userText)) {
    scopeCategory = 'account';
  } else if (/\b(deposit|withdraw|withdrawal|transfer|payment|funding|transaction)\b/i.test(userText)) {
    scopeCategory = 'funding';
  } else if (/\b(hi|hello|hey|good morning|good afternoon|good evening|thanks|thank you|how are you)\b/i.test(userText)) {
    scopeCategory = 'general_chat';
  }
}

if (scopeCategory === 'out_of_scope' && intentConfidence >= 0.55) {
  if (intent === 'account_inquiry') scopeCategory = 'account';
  if (intent === 'deposit_withdrawal') scopeCategory = 'funding';
  if (intent === 'technical_support') {
    const subIntentMap = {
      forgot_password_client_crm: 'credential_client_crm',
      forgot_password_trading_account: 'credential_trading_account',
      forgot_password_trading_app: 'credential_trading_app'
    };
    scopeCategory = subIntentMap[subIntent] || detectCredentialScope(userText) || scopeCategory;
  }
}

const in_scope = scopeCategory !== 'out_of_scope' && userText.length > 0;
const isCredentialScope = scopeCategory.startsWith('credential_');
const ticketConsentPattern = /\b(?:create|open|submit|raise)\s+(?:a\s+)?(?:support\s+)?(?:ticket|case)\b/i;
const explicitYesTicketPattern = /\b(?:yes|yeah|yep|ok|okay|sure|please do)\b.*\b(ticket|case)\b/i;
const wantsSupportTicket = isCredentialScope && (ticketConsentPattern.test(userText) || explicitYesTicketPattern.test(userText));

// Metadata allow-list for audit/compliance. Hard tool limit is from connected tools.
let allowed_tools = [];
if (scopeCategory === 'account') allowed_tools = ['get_account_summary'];
if (scopeCategory === 'funding') allowed_tools = ['get_transactions'];
if (isCredentialScope && wantsSupportTicket) {
  allowed_tools = ['create_support_ticket_api'];
}
const requires_tools = ['account', 'funding'].includes(scopeCategory);

const refusal_message = "I can still help with that at a general level. For direct account actions, I can currently check your account summary, your deposit/withdrawal transactions, and credential/login recovery for Client CRM or trading platforms.";
const safe_fallback_message = "I couldn't retrieve reliable data right now. Please try again or contact support.";
const router_status = userText ? 'ok' : 'degraded';

const shouldEscalate = (() => {
  if (!in_scope) return { escalate: false, reason: null };
  if (intent === 'escalation_request') return { escalate: true, reason: 'user_requested' };
  if (context.sentiment_score < -0.6 && context.sentiment === 'angry') return { escalate: true, reason: 'negative_sentiment' };
  if (context.user?.isVip && intent === 'complaint') return { escalate: true, reason: 'vip_complaint' };
  if ((dbConfig.recent_escalations || 0) >= 3) return { escalate: true, reason: 'recurring_issues' };
  return { escalate: false, reason: null };
})();

